def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    if n == 1:
        return [0]
    g = [[] for _ in range(n)]
    for a, b in edges:
        g[a].append(b)
        g[b].append(a)
    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in g[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)
    parent[0] = -1
    sub = w[:]
    down = [0] * n
    for u in reversed(order):
        p = parent[u]
        if p != -1:
            sub[p] += sub[u]
            down[p] += down[u] + sub[u]
    total = sub[0]
    ans = [0] * n
    ans[0] = down[0]
    for u in order:
        for v in g[u]:
            if v != parent[u]:
                ans[v] = ans[u] + total - 2 * sub[v]
    return ans
